chapter(5, 'The folio: charges, discounts and corrections', 'Open the folio of Rahul Deshmukh, post a laundry charge and a free-text charge, set the meal plan, see how a discount and a rate change go through approval.',
        'Priya (Cashier)', 'cashier', menu='Cash & Billing > Guests & folios')
read('You are Priya, the cashier, on Modules Home. The folio is the guest\'s running account: everything the guest owes and has paid.', 'Every rupee a guest pays or owes goes through the folio.', target='sel:.fit-home-grid', expect='Modules Home for Priya.')
tile('Cash & Billing', 'Click the Cash & Billing tile.', 'Folios, the cashier shift, the cash book, restaurant checks and expenses are here.', expect='The Cash & Billing page opens.')
leaf('Cash & Billing', 'Guests & folios', 'Click the Guests & folios tile.', 'This is the list of every guest bill.', expect='The Guests & folios page opens.', check="ctx.page==='folios'")
read('The chips All, In house, Due out, Balance due, Departed and Confirmed filter the list. Folio requests lists requests waiting for approval.', 'Cashiers use Due out and Balance due to prepare check-outs.', target='btn:Due out', expect='The folio filters.')
typ('field:Search', 'HCC-1101', 'Type the booking number HCC-1101.', 'The search also takes a name, a room, a company or an invoice number.', expect='Only the folio of Rahul Deshmukh is listed.')
click('btn:Rahul DeshmukhHCC-1101', 'Click the folio of Rahul Deshmukh.', 'The folio opens with his charges, receipts and action buttons.', expect='The folio of HCC-1101 opens.', check="has('Guest folio')")
read('The folio shows the charges with tax, the receipts and deposits, and the balance. Rahul\'s advance of Rs 2,000 is listed under receipts. Room nights are posted by the night audit, so there are no room lines yet.',
     'A cashier checks the folio before taking any payment.', target='sel:main h3', expect='The folio with the advance receipt.')
click('btn:Add charge', 'Click Add charge to post a service the guest used.', 'Charges come from the hotel\'s catalogue, so the price and the GST are always right.', expect='The Add a service charge dialog opens.', check="has('Post charge')")
pick('field:Item', 'Laundry', 'Choose Laundry, Rs 500 per bag, from the catalogue.', 'Laundry carries GST at 18 per cent, rooms at 5 per cent; HCC takes the rate from the GST master.', expect='Laundry selected.')
click('modalbtn:Post charge', 'Click Post charge.', 'The charge joins the folio with CGST and SGST shown separately.', expect='Laundry Rs 500 plus 18 per cent GST is on the folio.', check="has('Laundry')")
step('Click Add charge again. For something not in the catalogue, choose Other (describe) and type the details.', 'A free-text charge needs a clear description, because it is read later by the accountant and the guest.', target='field:Item',
     auto=['click:btn:Add charge', 'select:field:Item|Other (describe)'], action='select', expect='The form asks for a description and an amount.')
step('Describe it as Courier to Pune and enter the amount 200 rupees.', 'Free-text lines are taxed at 18 per cent as other services.', target='dialog:',
     auto=['type:field:Description|Courier to Pune', 'type:field:Amount|200'], action='type', expect='Description and amount filled.')
click('modalbtn:Post charge', 'Click Post charge.', 'Both charges are now on the folio.', expect='The courier charge is on the folio.', check="has('Courier')")
click('btn:Meal plan', 'Click Meal plan. Rahul booked bed and breakfast, CP.', 'The plan adds a breakfast line per guest per night.', expect='The Meal plan dialog opens.', check="has('Save plan')")
tick('field:Breakfast included', 'Choose Breakfast included (CP).', 'CP means continental plan: room and breakfast.', expect='CP is selected.')
click('modalbtn:Save plan', 'Click Save plan.', 'The breakfast lines will post with the room nights.', expect='The plan is saved.')
click('btn:Rate / guests', 'Click Rate / guests to see how a rate change is made.', 'A guest rate is never edited silently: the change needs a reason and an approval (rule CTL-01).', expect='The Rate / guest change dialog opens.', check="has('Request approval')")
read('The dialog shows the rate Rs 3,000, 2 guests, and asks when it applies. A reason is required, and the manager must approve before the new rate counts.', 'Without approval, nobody can lower a rate and pocket the difference.', target='dialog:', expect='The rate-change form.')
press('Escape', 'Press Escape. Rahul keeps the agreed rate, so request nothing.', 'Only a request that you submit goes to the manager.', target='sel:main h3', expect='The folio is shown.', check="!q('[role=dialog]')")
step('Reception offers a service-recovery discount for the noisy air conditioner. Aarav opens Rahul\'s booking in Reservations and clicks Discount.', 'A discount is a promise of money, so the front desk asks and the manager decides.', target='dialog:',
     auto=['user:reception', 'menu:Front Desk>Reservations', 'type:field:Search guest|HCC-1101', 'click:btn:Open Rahul Deshmukh', 'click:modalbtn:Discount'], action='click', expect='The Add a discount dialog opens.', check="has('Submit discount')")
step('Choose the reason Service recovery and type 150 rupees before GST. The rule allows at most 25 per cent of the charges posted so far.', 'The reason is mandatory and appears in the audit and the discount report.', target='field:Amount before GST',
     auto=['select:field:Reason|Service recovery', 'type:field:Amount before GST|150'], action='type', expect='Reason and amount filled.')
click('modalbtn:Submit discount', 'Click Submit discount.', 'The discount waits in the manager\'s approval list; the folio does not change yet.', expect='The discount request is submitted for approval.', msgText='Discount submitted for approval')
step('Meera, the Manager, opens Approvals & audit under Admin & Setup. The request waits in the Pending list.', 'The person who asks can never approve their own request.', target='sel:main h1',
     auto=['key:Escape', 'user:manager', 'menu:Admin & Setup>Approvals & audit'], action='click', menu='Admin & Setup > Approvals & audit', expect='The Approvals inbox shows one pending request.', check="ctx.page==='approvals'")
click('btn:Rahul Deshmukh · HCC-1101', 'Click the request to read it: the guest, the booking, the reason and the amount.', 'A manager approves only after reading what exactly is asked.', expect='The request opens with Approve and Reject buttons.', check="has('Approve')")
click('btn:Approve', 'Click Approve. Meera agrees to the service-recovery discount.', 'The approval is stamped with the name and time of the manager and written to the audit log; the discount is posted on the folio.', expect='The request is Approved and the discount is posted on the folio.')
step('Open Plans & extras under Accounts & Reports. It lists the meal plans and the extra-service catalogue with their prices.', 'The prices you chose from in this chapter come from here; the owner sets them in Masters.', target='sel:main h1',
     auto=['menu:Accounts & Reports>Plans & extras'], action='click', menu='Accounts & Reports > Plans & extras', expect='The Plans & extras page opens.', check="ctx.page==='plans-extras'")
